import{_ as i,l as r,o as a,c as s,v as t,p as l,x as n,d,i as p,S as h}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"Leave No Context Behind","description":"","frontmatter":{"title":"Leave No Context Behind","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/leave-no-context.md","filePath":"llm/leave-no-context.md","lastUpdated":1789023840000}'),E={name:"llm/leave-no-context.md"};function m(f,e,B,c,A,k){const o=r("Mermaid");return a(),s("div",null,[e[1]||(e[1]=t('<h1 id="leave-no-context-behind" tabindex="-1">Leave No Context Behind <a class="header-anchor" href="#leave-no-context-behind" aria-label="Permalink to &quot;Leave No Context Behind&quot;">​</a></h1><div class="epigraph"><p>标题里的承诺是：上下文不被滑窗丢掉，每一段都会进入压缩记忆；无限输入配上有界状态，而不是再开一条随长度上涨的 KV 日志。</p><footer>—— Munkhdalai, Faruqui &amp; Gopal，Leave No Context Behind，Google，arXiv:2404.07143，2024</footer></div><p>2024 年 Google 这篇预印本的正式标题是 <em>Leave No Context Behind: Efficient Infinite Context Transformers with Infini-attention</em>。注意力算子本身写在 <a href="/llm/infini-attn-paper">Infini-Attention 原文</a>；本篇读的是标题所立的研究命题：<strong>无限上下文 Transformer</strong> 要满足什么，现有方法在哪一环「把上下文留在了后面」，以及原文用 1B / 8B 继续预训练给出了哪些存在性证据。口号容易被读成无损信道；论文实际交付的是「写入规则不丢段、状态有界、局部 softmax 仍在」这一组工程约束。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>长上下文路线在 2023–2024 年已经分叉。一条把窗口硬拉到 128K、1M，KV 与计算仍随 \\(t\\) 涨，靠 FlashAttention、GQA、分块内核把常数压下去。另一条承认状态必须有界：滑窗、注意力汇点、StreamingLLM 只保留最近一段加少数锚点，<strong>中间 token 被显式丢掉</strong>。Compressive Transformer 把旧激活压进固定槽位，槽数仍随要覆盖多远而涨；Transformer-XL 缓存上一层的片段，覆盖半径等于缓存条数乘段长。Memorizing Transformer 用 kNN 外挂检索，索引随 \\(t\\) 涨。</p><p>「Leave no context behind」针对的正是第二条路上的<strong>丢段</strong>。滑窗与汇点在实现上最干净，但书中间某一段若从未进入状态，后文无法再读它——除非它碰巧被压进那几个锚点。无限上下文若允许中间空洞，就不是无限，只是局部加少数全局点。问题变成：有没有一种递推，使每一段都对未来可见，同时状态尺寸不随 \\(t\\) 线性膨胀？</p><h3 id="丢段是设计选择-不是实现疏忽" tabindex="-1">丢段是设计选择，不是实现疏忽 <a class="header-anchor" href="#丢段是设计选择-不是实现疏忽" aria-label="Permalink to &quot;丢段是设计选择，不是实现疏忽&quot;">​</a></h3><p>StreamingLLM 证明：许多预训练注意力会把质量堆在起始 token 上，于是可以丢掉中间 KV 仍保持流畅。这是「语言模型不需要中间」的经验，不是「中间信息已被保存」。对 passkey、合同条款、书中伏笔，中间恰恰是要留的。原文把这类方法放在对立面：它们优化的是有界缓存下的生成稳定性，优化目标里没有「每一段都写入」。Compressive Transformer 接近「不丢段」，但压缩槽随覆盖距离变长，无限时仍会碰到槽耗尽。需要的是槽数与 \\(t\\) 脱钩的压缩。</p><p><span class="marginnote">有界状态加上永不丢段，在信息论上只能是有损。\\(d\\times d\\) 矩阵的比特数是常数，无限 token 的熵不是。标题描述的是更新图没有丢弃边，不是信道容量无限。把论文读成「1M token 无损可逆」，是把口号当成定理。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>原文的答案是段级递推的 Infini-attention：当前段做因果 softmax，全部过去进压缩记忆 \\(M\\)，门控混合，然后用本段键值更新 \\(M\\)。段与段之间只传递 \\((M,z)\\)，不传递 KV。这在接口上像 Transformer-XL 的片段缓存，对象却从「上一层的激活条」换成了「与 \\(d\\) 有关的关联矩阵」。继续预训练成为可行路径：从已有 8K 级 LLM 出发，把注意力换成 Infini-attention，在更长数据上接着训，让门与记忆适应新的读写。</p><h3 id="继续预训练而不是从零发明记忆网络" tabindex="-1">继续预训练而不是从零发明记忆网络 <a class="header-anchor" href="#继续预训练而不是从零发明记忆网络" aria-label="Permalink to &quot;继续预训练而不是从零发明记忆网络&quot;">​</a></h3><p>1B 与 8B 量级的实验走的是持续预训练加下游任务，而不是随机初始化一个无限记忆 Transformer。这样做的动机很具体：局部 softmax 的短程语言建模已经由基座负责，新模块只需学会何时读 \\(M\\)、如何把长书与 passkey 写进 \\(M\\)。若从零训，必须同时学句法与记忆，预算会回到完整预训练。代价是：基座若从未见过段级递推，位置编码与段边界需要对齐；门若初始化成关闭记忆，长程信号一开始很弱，需要足够步数才打得开。</p><h3 id="评测协议-唯一针与长书" tabindex="-1">评测协议：唯一针与长书 <a class="header-anchor" href="#评测协议-唯一针与长书" aria-label="Permalink to &quot;评测协议：唯一针与长书&quot;">​</a></h3><p>原文用来支撑「无限」的，主要是超长 passkey 检索（报道到百万 token 量级）以及书籍级摘要（如 PG-19 一类长输入）。Passkey 几乎是对「写入有没有中断」的探针：针在键空间里足够独特，\\(M\\) 里不容易被淹没，绿分不证明密集干扰下仍可分。长书摘要更接近标题：中间章节必须留下痕迹，否则摘要会系统性漏情节。二者都不是多跳针测或仓库级代码。复现应对齐段长、是否用 delta 规则、继续预训练的 token 数；把报道长度理解成产品开关，比较的就不是这篇论文。</p>',15)),(a(),l(h,null,{default:n(()=>[p(o,{id:"mermaid-43",class:"mermaid",graph:"flowchart%20TD%0A%20%20WIN%5B%22%E6%BB%91%E7%AA%97%20%2F%20%E6%B1%87%E7%82%B9%22%5D%20--%3E%20DROP%5B%22%E4%B8%AD%E9%97%B4%E6%AE%B5%E8%A2%AB%E4%B8%A2%22%5D%0A%20%20XL%5B%22Transformer-XL%20%E7%BC%93%E5%AD%98%22%5D%20--%3E%20GROW%5B%22%E7%8A%B6%E6%80%81%E9%9A%8F%E8%A6%86%E7%9B%96%E5%8D%8A%E5%BE%84%E6%B6%A8%22%5D%0A%20%20CMP%5B%22Compressive%20%E6%A7%BD%22%5D%20--%3E%20GROW%0A%20%20MEM%5B%22kNN%20%E5%A4%96%E6%8C%82%E8%AE%B0%E5%BF%86%22%5D%20--%3E%20GROW%0A%20%20INF%5B%22Infini-attention%20%E9%80%92%E6%8E%A8%22%5D%20--%3E%20KEEP%5B%22%E6%AF%8F%E6%AE%B5%E5%86%99%E5%85%A5%20M%22%5D%0A%20%20KEEP%20--%3E%20BOUND%5B%22%E7%8A%B6%E6%80%81%20O(d%5E2)%20%E6%9C%89%E7%95%8C%22%5D%0A%20%20DROP%20--%3E%20GAP%5B%22%E4%B8%8A%E4%B8%8B%E6%96%87%E7%A9%BA%E6%B4%9E%22%5D%0A%20%20GROW%20--%3E%20LIM%5B%22%E8%A6%86%E7%9B%96%E8%B6%8A%E8%BF%9C%E8%B6%8A%E8%B4%B5%22%5D%0A"})]),fallback:n(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>「不丢上下文」在更新图上的含义是：不存在一条「段 \\(s\\) 计算完即删除、永不进入未来状态」的边。每一段的 \\(K,V\\) 都会经 \\(\\sigma(K)^\\top V\\) 或 delta 残差加进 \\(M\\)。未来任意段的查询都可以对 \\(M\\) 做线性读取。可见性是<strong>经压缩后的全局可见</strong>，不是对原始 token 的随机访问。这与 Longformer 的全局点不同：全局点仍指向具体 token；这里没有可索引的过去 token，只有矩阵里的叠加。</p><p>与丢段方法的机制对照可以写清楚。滑窗的归纳偏置是马尔可夫：再远的依赖必须已经写进近期表示。汇点把起始位置当成始终在场的锚，中间仍缺。Infini-attention 的归纳偏置是关联记忆：远依赖能留下的，是能被核特征寻址的方向。因此同一标题下，passkey 成功与「相似段落中找第三句」失败可以共存——前者满足寻址假设，后者在 \\(M\\) 里碰撞。Delta 规则提高后者的几率，仍受 \\(d^2\\) 容量限制。</p><h3 id="压缩比与「无限」的实验含义" tabindex="-1">压缩比与「无限」的实验含义 <a class="header-anchor" href="#压缩比与「无限」的实验含义" aria-label="Permalink to &quot;压缩比与「无限」的实验含义&quot;">​</a></h3><p>原文给出相对基线 Transformer 约 114 倍的记忆压缩，来自「存 \\(M\\) 而不存全长 KV」的比值，依赖段长与宽度。无限在实验里等于「测试长度远大于训练窗口，且状态尺寸不变」。它不是计算复杂度为零：段内仍 \\(O(N^2)\\)，总长 \\(T\\) 上前向仍与 \\(T\\) 线性。线性已经允许在固定显存里把 \\(T\\) 拉到设备算力的上限；这与「二次注意力硬吃 1M」不是同一档资源。把 1M passkey 写成「模型理解了百万上下文」，超出了探针所能见证的内容。</p><p><span class="marginnote">验收应至少两套针：几乎唯一的 passkey，以及埋在重复句式里的事实。前者只证明更新链没断；后者才逼近「leave no context」在有损记忆上还剩多少可分信息。两套都绿，才能说该任务族上压缩记忆可用。</span></p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>论文不提供可复现的万亿 token 配方，也不把 Google 内部数据配比写全。存在性证据绑定在继续预训练、段长、门控与 delta 的具体选择上。服务侧必须把 \\((M,z)\\) 当成新的状态类型：中断后续写若丢掉 \\(M\\)，无限立刻退回滑窗。这与普通 KV 缓存的序列化不兼容。若产品需要逐字引用，应外接检索；矩阵记忆匹配的是摘要、唯一针、以及「读过即可」的全局草图。</p><p>标题还容易与「上下文窗口扩展」混为一谈。YaRN、位置插值拉的是 RoPE 模型的可寻址下标，KV 仍随 \\(t\\) 涨。Infini-attention 拉的是状态对象的数学形式。二者可以叠：段内用扩展过的 RoPE softmax，段间用 \\(M\\)。不要用其中一条的评测表给另一条背书。也不要把 StreamingLLM 的流畅度增益当成「中间上下文其实不重要」——那是另一篇论文的任务分布。</p><p><span class="marginnote">与 RMT、Landmark、Activation Beacon 的差别在接口。那些方法仍在 softmax 里放置可见的压缩 token；Infini 的 \\(M\\) 对后续 token 不是普通键。调试与可视化的工具链要从注意力图换成门值与 \\(M\\) 的谱。口号级引用若只写「Google 的无限上下文」，应落到这一接口差异上。</span></p><h3 id="何时不该用这组约束" tabindex="-1">何时不该用这组约束 <a class="header-anchor" href="#何时不该用这组约束" aria-label="Permalink to &quot;何时不该用这组约束&quot;">​</a></h3><p>需要精确拷贝远处罕见标识符、需要多层多跳、需要把过去某一 token 当普通 KV 取回时，有界关联记忆不是合适的主结构。需要在冻结权重上即插即用时，也不该宣称本篇方法。匹配的场景是：愿意为记忆通路花钱继续预训练，任务容忍有损全局草图，并且接受段内窗口仍二次。满足这些，标题里的约束才是设计目标而不是营销。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Leave No Context Behind 要的是：每段都写入、状态有界、局部 softmax 仍在，而不是无损无限日志。</li><li>对立面是滑窗与汇点的丢段，以及 XL / 压缩槽 / kNN 随覆盖距离涨的状态。</li><li>证据主场是超长 passkey 与长书摘要；密集干扰与多跳不在同一探针上。</li><li>继续预训练让算子接到已有 LLM；服务必须持久化 \\((M,z)\\)。</li><li>有界加不丢段必然有损；\\(d^2\\) 容量是硬上限。</li><li>出处：Munkhdalai, Faruqui &amp; Gopal，<em>Leave No Context Behind: Efficient Infinite Context Transformers with Infini-attention</em>，arXiv:2404.07143，2024。</li></ul>',14))])}const M=i(E,[["render",m]]);export{u as __pageData,M as default};
